package com.MITProjectService.bot.dao.jpaRepos.specification;import com.MITProjectService.bot.domain.ServiceProvider;import com.MITProjectService.bot.request.UserPaymentAccountRequest;import org.springframework.data.jpa.domain.Specification;import org.springframework.stereotype.Service;@Servicepublic class UserPaymentAccountSpecification {    public static Specification<UserPaymentAccountRequest> byServiceProvider(ServiceProvider serviceProvider) {        return (root, query, cb) -> cb.equal(root.get("serviceProvider"), serviceProvider);    }}